function s(v) { return String(v == null ? '' : v).trim(); }
function nz(x) { return s(x).toLowerCase().replace(/[^a-z0-9]/g, ''); }
const v = $('GET STARTUPS').first().json.values || [];
if (v.length < 40) { throw new Error('ABORT: STARTUPS only ' + v.length); }
const h = (v[0] || []).map(s);
const I = {}; ['startup','stage','revenue','raise_inr_cr','memo_body','memo_html','highlight_1','highlight_2','highlight_3','active'].forEach(function (n) { I[n] = h.indexOf(n); if (I[n] < 0) { throw new Error('ABORT: STARTUPS missing ' + n); } });
const WANT = {};
['AI Signal Labs','Desi Machines','Road Athena','Chayan Karo','Doffair','Ela Greens','bezgoFresh','DACBY'].forEach(function (n) { WANT[nz(n)] = n; });
function strip(html) { return s(html).replace(/<[^>]*>/g, ' ').replace(/&amp;/g, '&').replace(/&nbsp;/g, ' ').replace(/&mdash;/g, '-').replace(/&ndash;/g, '-').replace(/&rsquo;/g, "'").replace(/\s+/g, ' '); }
const MONEY = /(revenue|arr\b|mrr\b|gmv|run-?rate|turnover|topline|billings?|profitab|ebitda|earning|monetis|monetiz|paying|subscription|take rate|commission)/i;
const out = [];
for (let r = 1; r < v.length; r++) { const row = v[r] || []; const n = s(row[I.startup]); if (!n) { continue; }
  const k = nz(n); if (!WANT[k]) { continue; }
  const text = strip(row[I.memo_body]) + ' ' + strip(row[I.memo_html]);
  const sentences = text.split(/(?<=[.;])\s+|\s\|\s/);
  const seen = {}; const hits = [];
  for (const sen of sentences) { const t = s(sen); if (t.length < 8 || t.length > 320) { continue; }
    if (!MONEY.test(t)) { continue; }
    const key = t.slice(0, 60).toLowerCase(); if (seen[key]) { continue; } seen[key] = 1;
    hits.push(t); }
  out.push({ startup: n, stage: s(row[I.stage]), revenue_column: s(row[I.revenue]), raise: s(row[I.raise_inr_cr]),
    highlights: [s(row[I.highlight_1]), s(row[I.highlight_2]), s(row[I.highlight_3])],
    revenue_mentions: hits.slice(0, 14) }); }
if (out.length !== 8) { throw new Error('ABORT: expected 8 startups, matched ' + out.length + ': ' + out.map(function (x) { return x.startup; }).join(', ')); }
return [{ json: { count: out.length, startups: out } }];
